//! Writes `globals.wasm` to the directory supplied as the first argument.
//!
//! Usage: gen_globals <output-dir>
//!
//! The file is generated by `test_types::globals::globals_wasm()` — a
//! pure-Rust encoder that is separately unit-tested. This binary exists only
//! to write those bytes to disk so the CI job can compare the result against
//! the committed copy in `pkg/globals.wasm`.

use std::fs;
use std::path::PathBuf;

fn main() {
    let dir: PathBuf = std::env::args_os()
        .nth(1)
        .expect("usage: gen_globals <output-dir>")
        .into();

    fs::create_dir_all(&dir).expect("could not create output directory");

    let bytes = test_types::globals::globals_wasm();
    let out = dir.join("globals.wasm");
    fs::write(&out, &bytes).expect("could not write globals.wasm");
}
